--- SCREEN: Parent category → child category (sidebar link) ---
[ASSERT] browser_snapshot the category page; pick a child/subcategory link in the sidebar or sub-nav → store its name as {child_category_name}
[SETUP] `browser_evaluate` (read-only DOM instrumentation, installed BEFORE the real action — sidebar click, never a reload — the observers survive the SPA route change; a MutationObserver + ResizeObserver queue every slot change in order, so the transient loader window is never missed): const c=document.querySelector('.search-bar .vc-input__decorator'); const inp=document.querySelector('[data-test-id=global-search-query-input]'); window.__tl=[]; const snap=()=>{ const kids=c?Array.from(c.children):[]; const chips=kids.filter(el=>el.matches('[data-search-scope]')); window.__tl.push({t:performance.now(), slotWidth:kids.reduce((s,el)=>s+el.getBoundingClientRect().width,0), loaderCount:kids.filter(el=>!el.matches('[data-search-scope]')).length, chipCount:chips.length, chipLabels:chips.map(el=>(el.querySelector('.vc-button__slot')?.textContent||el.getAttribute('data-search-scope')||'').trim()), placeholder:inp?inp.getAttribute('placeholder'):null, inputLeft:inp?inp.getBoundingClientRect().left:null}); }; snap(); const mo=new MutationObserver(snap); if(c) mo.observe(c,{childList:true,subtree:true,characterData:true,attributes:true}); const mp=new MutationObserver(snap); if(inp) mp.observe(inp,{attributes:true,attributeFilter:['placeholder']}); const ro=new ResizeObserver(snap); if(c) ro.observe(c); window.__obs=[mo,mp,ro]; return {installed:true, baseline:window.__tl[0]}; — confirm installed===true
[ACT] Click the child category link labeled "{child_category_name}" (a real user click)
[WAIT] Child category page loads; scope chip settles naming {child_category_name}
[SETUP] `browser_evaluate` (read-only replay of the recorded timeline after the transition settled; observers disconnected first so the array is frozen): window.__obs?.forEach(o=>o.disconnect()); const tl=window.__tl||[]; const le=tl.filter(e=>e.loaderCount>=1); const lefts=le.map(e=>e.inputLeft); const last=le[le.length-1]; const after=last?tl.slice(tl.indexOf(last)+1).find(e=>e.loaderCount===0&&e.chipCount>=1):null; const st=tl[tl.length-1]||{}; return {timeline:tl, minSlotWidth:Math.min(...tl.map(e=>e.slotWidth)), maxSimultaneous:tl.reduce((m,e)=>Math.max(m,(e.loaderCount>=1&&e.chipCount>=1)?(e.loaderCount+e.chipCount):0),0), loaderEntryCount:le.length, inputSpanInLoader:lefts.length?Math.max(...lefts)-Math.min(...lefts):null, swapLeftDelta:(last&&after)?Math.abs(after.inputLeft-last.inputLeft):null, settledLoaderCount:st.loaderCount, settledChipCount:st.chipCount, settledChipLabels:st.chipLabels, settledPlaceholder:st.placeholder, h1:(document.querySelector('h1')?.textContent||'').trim()}; — store minSlotWidth as {leg1_min_slot_width}, maxSimultaneous as {leg1_max_simultaneous}, loaderEntryCount as {leg1_loader_entry_count}, inputSpanInLoader as {leg1_input_span_in_loader}, swapLeftDelta as {leg1_swap_left_delta}, settledLoaderCount as {leg1_settled_loader_count}, settledChipCount as {leg1_settled_chip_count}, settledChipLabels as {leg1_settled_chip_labels}, settledPlaceholder as {leg1_settled_placeholder}, h1 as {leg1_h1}, the full timeline as {leg1_timeline} (evidence only)
